<script setup lang="ts">
import { computed, onBeforeUnmount, ref, watch } from 'vue'
import { useWorkspaceStore } from '../stores/workspace'
import { opsApi } from '../services/operations'
import type { BusinessEvent, BusinessObject, Guidance, Impact, ObjectPage, OperationsCatalog, Registry, WorkOrder } from '../types/operations'
import type { FeatureCollection } from '../types/api'
const props=defineProps<{active:boolean}>()
const emit=defineEmits<{map:[geo:FeatureCollection,title:string,key:string];selectArea:[];close:[]}>()
const store=useWorkspaceStore(),tab=ref('overview'),catalog=ref<OperationsCatalog>(),registries=ref<Registry[]>([]),events=ref<BusinessEvent[]>([]),tasks=ref<WorkOrder[]>([]),guidances=ref<Guidance[]>([])
const busy=ref(false),loading=ref(false),error=ref(''),notice=ref(''),actor=ref(''),registryId=ref(''),query=ref(''),statusQuery=ref(''),page=ref<ObjectPage>(),offset=ref(0),selectedObject=ref<BusinessObject>(),selectedTask=ref<WorkOrder>(),eventId=ref(''),impact=ref<Impact>(),selectedTargets=ref<string[]>([]),scopeIds=ref<string[]>([])
const registryForm=ref({name:'',kind:'farmland',source:'',year:new Date().getFullYear()}),importForm=ref({dataset_id:'',code_field:'',name_field:'',status_field:''}),eventForm=ref({title:'',hazard:'flood',source_name:'',source_kind:'manual',issued_at:new Date(Date.now()-new Date().getTimezoneOffset()*60000).toISOString().slice(0,16)}),assignment=ref({assignee:'',due_date:new Date(Date.now()+86400000).toISOString().slice(0,10)}),feedback=ref({note:'',finding:'unknown',evidence:''}),objectForm=ref({status:'',progress:0,note:''}),guidanceForm=ref({title:'',content:'',registry_id:''})
const impactOffset=ref(0),visibleImpacts=computed(()=>impact.value?.objects.slice(impactOffset.value,impactOffset.value+200)||[])
const fileInput=ref<HTMLInputElement>(),importProgress=ref(''),taskFilter=ref('all'),taskQuery=ref('')
const registry=computed(()=>registries.value.find(r=>r.id===registryId.value)),userData=computed(()=>store.datasets.filter(d=>d.source_type==='user')),selectedDataset=computed(()=>userData.value.find(d=>d.id===importForm.value.dataset_id))
const taskLabels:Record<string,string>={assigned:'待接单',processing:'处理中',submitted:'待审核',returned:'退回补充',closed:'已归档'}
const moduleLabels:Record<string,string>={registry:'可建档与更新',workflow:'可执行本机流程',reserved:'预留',awaiting_integration:'待业务接口'}
const visibleTasks=computed(()=>tasks.value.filter(t=>(taskFilter.value==='all'||t.status===taskFilter.value)&&[t.title,t.assignee,t.object.code].join(' ').includes(taskQuery.value.trim())))
let generation=0,objectsGeneration=0,controller:AbortController|undefined,disposed=false
function kindName(kind:string){return catalog.value?.kinds.find(k=>k.id===kind)?.name || kind}
function fail(e:unknown){error.value=e instanceof Error?e.message:'操作未完成'}
async function work(fn:()=>Promise<void>){if(busy.value)return;busy.value=true;error.value='';notice.value='';try{if(!actor.value.trim())throw Error('请填写操作人，用于本机业务留痕');await fn()}catch(e){fail(e)}finally{busy.value=false}}
async function refresh(){
 const id=++generation;controller?.abort();controller=new AbortController();loading.value=true;const signal=controller.signal
 const results=await Promise.allSettled([opsApi<OperationsCatalog>('/catalog',{signal}),opsApi<{registries:Registry[]}>('/registries',{signal}),opsApi<{items:BusinessEvent[]}>('/events',{signal}),opsApi<{items:WorkOrder[]}>('/tasks',{signal}),opsApi<{items:Guidance[]}>('/guidance',{signal})])
 if(disposed||id!==generation)return
 const failures:string[]=[]
 results.forEach((r,i)=>{if(r.status==='rejected'){failures.push(r.reason instanceof Error?r.reason.message:'读取失败');return}if(i===0)catalog.value=r.value as OperationsCatalog;else if(i===1)registries.value=(r.value as {registries:Registry[]}).registries;else if(i===2)events.value=(r.value as {items:BusinessEvent[]}).items;else if(i===3)tasks.value=(r.value as {items:WorkOrder[]}).items;else guidances.value=(r.value as {items:Guidance[]}).items})
 loading.value=false;if(failures.length)error.value='部分内容未更新，已有内容保留：'+failures.join('；')
}
watch(()=>props.active,value=>{if(value)void refresh();else{++generation;controller?.abort();loading.value=false}},{immediate:true})
onBeforeUnmount(()=>{disposed=true;++generation;++objectsGeneration;controller?.abort()})
async function loadObjects(){
 const id=++objectsGeneration;if(!registryId.value){page.value=undefined;return}
 try{const p=await opsApi<ObjectPage>('/objects?'+new URLSearchParams({registry_id:registryId.value,q:query.value,status:statusQuery.value,limit:'50',offset:String(offset.value)}));if(!disposed&&id===objectsGeneration)page.value=p}catch(e){if(id===objectsGeneration)fail(e)}
}
watch(registryId,()=>{offset.value=0;page.value=undefined;selectedObject.value=undefined;void loadObjects()})
function mapObjects(objects:BusinessObject[],title:string,key:string){if(!objects.length){error.value='没有可上图对象';return}emit('map',{type:'FeatureCollection',features:objects.map(o=>({type:'Feature',id:o.id,geometry:o.geometry,properties:{...o.properties,业务编码:o.code,业务名称:o.name,业务状态:o.status,对象版本:o.revision,台账编号:o.registry_id}}))},title,key)}
function showEvent(){const e=events.value.find(e=>e.id===eventId.value);if(e)emit('map',{type:'FeatureCollection',features:[{type:'Feature',geometry:e.geometry,properties:{事件:e.title,来源:e.source_name,性质:e.notice}}]},e.title,e.id)}
async function createRegistry(){await work(async()=>{const result=await opsApi<Registry>('/registries',{method:'POST',body:{...registryForm.value,actor:actor.value}});await refresh();registryId.value=result.id;notice.value='台账已建立，可从已有图层或GeoJSON分批入库。'})}
async function importDataset(){await work(async()=>{if(!registry.value||!selectedDataset.value)throw Error('请选择台账和用户图层');const r=await opsApi<{imported_count:number}>('/registries/'+registryId.value+'/import',{method:'POST',body:{...importForm.value,batch_id:selectedDataset.value.id,expected_revision:registry.value.revision,actor:actor.value}});await refresh();await loadObjects();notice.value='已核验入库 '+r.imported_count+' 个对象。'})}
async function importFile(event:Event){const file=(event.target as HTMLInputElement).files?.[0];if(!file)return
 await work(async()=>{
  if(!registry.value)throw Error('请先选择台账');if(!importForm.value.code_field.trim())throw Error('请填写稳定的业务编码字段，例如parcel_code')
  if(file.size>32*1024*1024)throw Error('交互导入最多32MiB；更大台账请通过分批接口入库')
  const targetId=registryId.value,actorName=actor.value,mapping={code_field:importForm.value.code_field,name_field:importForm.value.name_field,status_field:importForm.value.status_field},initialRevision=registry.value.revision
  const geo=JSON.parse(await file.text());if(geo?.type!=='FeatureCollection'||!Array.isArray(geo.features)||!geo.features.length)throw Error('请选择非空GeoJSON FeatureCollection')
  const inputHash=Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',await file.arrayBuffer()))).map(n=>n.toString(16).padStart(2,'0')).join('')
  let rev=initialRevision,batch:Record<string,unknown>[]=[],bytes=0,batchNumber=0,imported=0
  const send=async()=>{if(!batch.length)return;importProgress.value='正在入库，第'+(++batchNumber)+'批';const r=await opsApi<{registry_revision:number;imported_count:number}>('/registries/'+targetId+'/import',{method:'POST',body:{geojson:{type:'FeatureCollection',features:batch},...mapping,batch_id:inputHash.slice(0,32)+'-'+batchNumber,expected_revision:rev,actor:actorName}});rev=r.registry_revision;imported+=r.imported_count;batch=[];bytes=0}
  try{for(const f of geo.features){const size=new TextEncoder().encode(JSON.stringify(f)).length;if(size>1200000)throw Error('单个对象过大，请简化或通过专业工具分区导入');if(batch.length>=300||bytes+size>1200000)await send();batch.push(f);bytes+=size}await send();notice.value='入库完成，共核验 '+imported+' 个对象。'}finally{importProgress.value='';await refresh();await loadObjects()}
 });if(fileInput.value)fileInput.value.value=''
}
function editObject(o:BusinessObject){selectedObject.value=o;objectForm.value={status:o.status,progress:o.progress??0,note:''}}
async function saveObject(){await work(async()=>{if(!selectedObject.value)return;await opsApi('/objects/'+selectedObject.value.id,{method:'PATCH',body:{...objectForm.value,expected_revision:selectedObject.value.revision,actor:actor.value}});selectedObject.value=undefined;await refresh();await loadObjects();notice.value='状态与进度已保存，原修改过程可追溯。'})}
async function createEvent(){await work(async()=>{if(!store.area)throw Error('请先在地图选择核查范围');const [w,s,e,n]=store.area.bbox;const r=await opsApi<BusinessEvent>('/events',{method:'POST',body:{...eventForm.value,actor:actor.value,issued_at:new Date(eventForm.value.issued_at).toISOString(),geometry:{type:'Polygon',coordinates:[[[w,s],[e,s],[e,n],[w,n],[w,s]]]}}});await refresh();eventId.value=r.id;impact.value=undefined;notice.value='已登记人工研判事件，下一步选择业务台账进行空间核查。'})}
async function analyze(){await work(async()=>{if(!eventId.value||!scopeIds.value.length)throw Error('请选择事件和核查台账');impact.value=await opsApi<Impact>('/events/'+eventId.value+'/analyze',{method:'POST',body:{registry_ids:scopeIds.value,actor:actor.value}});impactOffset.value=0;selectedTargets.value=impact.value.objects.slice(0,200).map(o=>o.id);mapObjects(impact.value.objects.slice(0,200),'空间相交待核查对象（前200个）',impact.value.id);notice.value='已完成实际几何相交计算；地图分批显示，统计包含全部命中对象。'})}
async function dispatch(){await work(async()=>{if(!impact.value)return;await opsApi('/impacts/'+impact.value.id+'/dispatch',{method:'POST',body:{object_ids:selectedTargets.value,...assignment.value,actor:actor.value}});await refresh();tab.value='tasks';notice.value='核查任务已派发，可接单、回传和审核归档。'})}
function selectTask(t:WorkOrder){selectedTask.value=t;feedback.value={note:'',finding:'unknown',evidence:''}}
async function transition(status:string){await work(async()=>{if(!selectedTask.value)return;const body:Record<string,unknown>={status,note:feedback.value.note,actor:actor.value,expected_revision:selectedTask.value.revision};if(status==='submitted'){body.finding=feedback.value.finding;body.evidence_urls=feedback.value.evidence.split('\n').map(s=>s.trim()).filter(Boolean)}const updated=await opsApi<WorkOrder>('/tasks/'+selectedTask.value.id+'/transition',{method:'POST',body});feedback.value.note='';selectedTask.value=updated;await refresh();notice.value='任务已更新：'+taskLabels[status]})}
async function draftGuidance(){await work(async()=>{await opsApi('/guidance',{method:'POST',body:{...guidanceForm.value,actor:actor.value}});await refresh();notice.value='指导草稿已保存，审核发布后生成执行任务。'})}
async function publish(g:Guidance){await work(async()=>{await opsApi('/guidance/'+g.id+'/publish',{method:'POST',body:{expected_revision:g.revision,actor:actor.value,...assignment.value}});await refresh();notice.value='指导已审核发布，执行任务已生成。'})}
async function exportEvent(){try{if(!eventId.value)return;const result=await opsApi('/events/'+eventId.value+'/export');const url=URL.createObjectURL(new Blob([JSON.stringify(result,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download=eventId.value+'-核查档案.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}catch(e){fail(e)}}
watch(eventId,()=>{impact.value=undefined;selectedTargets.value=[]})
</script>
<template><section class="map-copilot agriculture-operations" aria-label="农业业务工作台"><header class="ops-heading"><div><small>农业管理 · 一张图</small><h2>业务工作台</h2></div><div class="ops-heading-actions"><button class="btn" :disabled="loading||busy" @click="refresh">刷新业务</button><button class="btn ops-map-return" aria-label="收起农业业务面板" @click="emit('close')">看地图</button></div></header><div class="ops-tabs" role="tablist" aria-label="农业业务"><button v-for="t in [{id:'overview',name:'概览'},{id:'registry',name:'台账'},{id:'events',name:'防灾核查'},{id:'tasks',name:'任务'},{id:'guidance',name:'生产指导'}]" :key="t.id" role="tab" :aria-selected="tab===t.id" @click="tab=t.id">{{t.name}}</button></div><div class="ops-scroll"><p v-if="error" class="ops-error" role="alert">{{error}}</p><p v-if="notice" class="ops-notice" role="status">{{notice}}</p><label class="ops-field ops-actor">操作人<input v-model="actor" :disabled="busy" placeholder="姓名或业务岗位（本机留痕）" maxlength="100"></label>
 <template v-if="tab==='overview'"><div class="ops-metrics"><div><b>{{registries.reduce((s,r)=>s+r.object_count,0)}}</b><span>已建档对象</span></div><div><b>{{tasks.filter(t=>t.status!=='closed').length}}</b><span>待办任务</span></div><div><b>{{tasks.filter(t=>t.status==='closed').length}}</b><span>已归档</span></div></div><p class="ops-help">建档 → 范围研判 → 派单核查 → 回传归档。各业务共用地图与对象档案。</p><div class="ops-module-grid"><button v-for="m in catalog?.modules" :key="m.id" class="ops-module" @click="tab=m.id==='disaster'?'events':m.id==='guidance'?'guidance':m.status==='registry'?'registry':'overview';notice=m.note"><b>{{m.name}}</b><span>{{moduleLabels[m.status]}}</span><small>{{m.note}}</small></button></div><details class="ops-section"><summary>数据接入情况</summary><p v-for="c in catalog?.connections" :key="c.id">{{c.name}} <span class="ops-tag">待接入</span></p></details></template>
 <template v-else-if="tab==='registry'"><h3>业务台账</h3><label class="ops-field">选择台账<select v-model="registryId"><option value="">请选择台账</option><option v-for="r in registries" :key="r.id" :value="r.id">{{r.name}} · {{r.object_count}}个对象</option></select></label><details class="ops-section"><summary>新建台账</summary><form @submit.prevent="createRegistry"><label class="ops-field">台账名称<input v-model="registryForm.name" required placeholder="例如：高标准农田项目台账"></label><label class="ops-field">台账类别<select v-model="registryForm.kind"><option v-for="k in catalog?.kinds" :key="k.id" :value="k.id">{{k.name}}</option></select></label><label class="ops-field">业务年度<input v-model.number="registryForm.year" type="number" min="1900" max="2200" required></label><label class="ops-field">台账来源<input v-model="registryForm.source" required placeholder="提供单位、数据文件或调查批次"></label><button class="btn primary" :disabled="busy">建立台账</button></form></details>
 <template v-if="registry"><p class="ops-help">{{kindName(registry.kind)}} · {{registry.year||'年度未提供'}} · 来源：{{registry.source}} · 台账版本{{registry.revision}}</p><details class="ops-section"><summary>导入业务对象</summary><p class="ops-help">稳定业务编码用于防止重复入库。可导入已有图层，或将较大GeoJSON自动分批入库。分批导入失败时，已完成批次保留，重试相同文件复用原批次。</p><label class="ops-field">业务编码字段<input v-model="importForm.code_field" placeholder="例如：parcel_code 或 项目编号"></label><label class="ops-field">名称字段（可选）<input v-model="importForm.name_field" placeholder="例如：name"></label><label class="ops-field">状态字段（可选）<input v-model="importForm.status_field" placeholder="例如：status"></label><label class="ops-field">已有用户图层<select v-model="importForm.dataset_id"><option value="">请选择上传图层</option><option v-for="d in userData" :key="d.id" :value="d.id">{{d.name}}</option></select></label><button class="btn primary" :disabled="busy||!importForm.dataset_id" @click="importDataset">从图层入库</button><label class="ops-field ops-file">批量GeoJSON文件<input ref="fileInput" type="file" accept=".geojson,.json" :disabled="busy" @change="importFile"></label><p v-if="importProgress" role="status">{{importProgress}}</p></details><form class="ops-search" @submit.prevent="offset=0;loadObjects()"><input v-model="query" aria-label="查找业务对象" placeholder="按名称或业务编码查找"><input v-model="statusQuery" aria-label="业务状态筛选" placeholder="状态（精确匹配）"><button class="btn">查询对象</button></form><div class="ops-list-toolbar"><span>共{{page?.total??'—'}}个对象</span><button class="btn" :disabled="!page?.items.length" @click="mapObjects(page!.items,registry.name+' · 当前页',registry.id)">当前页上图</button></div><p v-if="page?.total===0" class="ops-help">暂无匹配对象，可导入实际台账或调整筛选。</p><article v-for="o in page?.items" :key="o.id" class="ops-card"><header><b>{{o.name}}</b><span class="ops-tag">{{o.status}}</span></header><p>{{o.code}} · 对象版本{{o.revision}}</p><p v-if="o.progress!==undefined">建设进度 {{o.progress}}%</p><div class="ops-actions"><button class="btn" @click="mapObjects([o],o.name,o.id)">定位对象</button><button class="btn" @click="editObject(o)">更新档案</button></div></article><div class="ops-actions" v-if="page"><button class="btn" :disabled="offset===0" @click="offset=Math.max(0,offset-50);loadObjects()">上一页</button><button class="btn" :disabled="!page.has_more" @click="offset+=50;loadObjects()">下一页</button></div><form v-if="selectedObject" class="ops-section" @submit.prevent="saveObject"><h4>更新 {{selectedObject.name}}</h4><label class="ops-field">业务状态<input v-model="objectForm.status" required></label><label class="ops-field">进度百分比<input v-model.number="objectForm.progress" type="number" min="0" max="100"></label><label class="ops-field">更新说明<textarea v-model="objectForm.note" required/></label><button class="btn primary" :disabled="busy">保存档案更新</button></form></template></template>
 <template v-else-if="tab==='events'"><h3>防灾范围核查</h3><p class="ops-help">登记人工研判或转录事件，计算与台账的实际几何相交对象。结果是待核查范围，不是受灾面积认定。</p><details class="ops-section"><summary>登记核查事件</summary><form @submit.prevent="createEvent"><label class="ops-field">事件名称<input v-model="eventForm.title" required></label><label class="ops-field">灾害场景<select v-model="eventForm.hazard"><option v-for="h in catalog?.hazards" :key="h.id" :value="h.id">{{h.name}}</option></select></label><label class="ops-field">事件来源类型<select v-model="eventForm.source_kind"><option value="manual">人工研判</option><option value="transcribed">业务材料转录</option></select></label><label class="ops-field">来源单位或材料<input v-model="eventForm.source_name" required></label><label class="ops-field">来源时间<input v-model="eventForm.issued_at" type="datetime-local" required></label><p class="ops-help">{{store.area?store.area.name+' · '+store.area.bbox.join(', '):'尚未选择事件核查范围'}}</p><button type="button" class="btn" @click="emit('selectArea')">地图选择核查范围</button><button class="btn primary" :disabled="busy||!store.area">保存核查事件</button></form></details><label class="ops-field">选择核查事件<select v-model="eventId"><option value="">请选择事件</option><option v-for="e in events" :key="e.id" :value="e.id">{{e.title}}</option></select></label><div v-if="eventId" class="ops-actions"><button class="btn" @click="showEvent">事件范围上图</button><button class="btn" @click="exportEvent">导出核查档案</button></div><fieldset class="ops-section"><legend>参与空间核查的台账</legend><label v-for="r in registries" :key="r.id" class="ops-check"><input v-model="scopeIds" type="checkbox" :value="r.id">{{r.name}} · {{r.object_count}}个对象</label><p v-if="!registries.length" class="ops-help">先在台账中建立对象档案。</p></fieldset><button class="btn primary" :disabled="busy||!eventId||!scopeIds.length" @click="analyze">分析待核查对象</button><section v-if="impact" class="ops-section"><h4>空间相交 {{impact.object_count}}个对象</h4><a class="btn" :href="'/api/agri-operations/impacts/'+impact.id+'/geojson'" :download="impact.id+'.geojson'">下载全部待核查对象GeoJSON</a><p class="ops-help">{{impact.notice}} 边界接触{{impact.boundary_only_contacts}}个，单独列示。</p><p v-for="(n,k) in impact.counts" :key="k">{{kindName(String(k))}} · {{n}}个</p><p class="ops-help">每次可选最多200个对象派单。</p><label v-for="o in visibleImpacts" :key="o.id" class="ops-check"><input v-model="selectedTargets" type="checkbox" :value="o.id">{{o.name}} · {{o.code}}</label><div class="ops-actions"><button class="btn" :disabled="impactOffset===0" @click="impactOffset=Math.max(0,impactOffset-200);selectedTargets=visibleImpacts.map(o=>o.id)">上一批对象</button><button class="btn" :disabled="impactOffset+200>=impact.objects.length" @click="impactOffset+=200;selectedTargets=visibleImpacts.map(o=>o.id)">下一批对象</button><button class="btn" @click="mapObjects(visibleImpacts,'当前批待核查对象',impact.id)">本批对象上图</button></div><label class="ops-field">责任单位或人员<input v-model="assignment.assignee"></label><label class="ops-field">完成日期<input v-model="assignment.due_date" type="date"></label><button class="btn primary" :disabled="busy||!selectedTargets.length" @click="dispatch">派发核查任务</button></section></template>
 <template v-else-if="tab==='tasks'"><h3>任务办理与归档</h3><div class="ops-search"><input v-model="taskQuery" aria-label="查找业务任务" placeholder="名称、责任人或业务编码"><select v-model="taskFilter" aria-label="任务办理状态"><option value="all">全部状态</option><option v-for="(v,k) in taskLabels" :key="k" :value="k">{{v}}</option></select></div><p v-if="!visibleTasks.length" class="ops-help">暂无匹配任务。</p><article v-for="t in visibleTasks" :key="t.id" class="ops-card"><header><b>{{t.title}}</b><span class="ops-tag">{{taskLabels[t.status]}}</span></header><p>{{t.assignee}} · 期限{{t.due_date}}</p><button class="btn" :disabled="busy" @click="selectTask(t)">办理任务</button><button class="btn" @click="mapObjects([t.object],t.title,t.id)">任务对象上图</button></article><section v-if="selectedTask" class="ops-section"><h4>{{selectedTask.title}}</h4><p>{{taskLabels[selectedTask.status]}} · 任务版本{{selectedTask.revision}}</p><p v-if="selectedTask.instruction">{{selectedTask.instruction}}</p><div v-if="selectedTask.feedback" class="ops-feedback"><b>现场或执行回执</b><p>{{selectedTask.feedback.note}}</p><p>提交人：{{selectedTask.feedback.submitted_by}}</p><a v-for="u in selectedTask.feedback.evidence_urls" :key="u" :href="u" target="_blank" rel="noopener noreferrer">查看证据链接</a></div><p v-if="selectedTask.review">审核人：{{selectedTask.review.actor}} · {{selectedTask.review.note}}</p><template v-if="selectedTask.status!=='closed'"><label class="ops-field">处理或审核说明<textarea v-model="feedback.note" :disabled="busy" placeholder="填写接单、现场情况或审核意见"/></label><template v-if="['processing','returned'].includes(selectedTask.status)"><label class="ops-field">现场核查或执行结果<select v-model="feedback.finding"><option value="unknown">待进一步核实</option><option value="normal">现场正常</option><option value="affected">现场发现受影响情况</option><option value="needs_support">需要资源支援</option><option value="completed">指导任务已执行</option></select></label><label class="ops-field">证据链接（可选，每行一个HTTPS链接）<textarea v-model="feedback.evidence"/></label></template><div class="ops-actions"><button v-if="['assigned','returned'].includes(selectedTask.status)" class="btn primary" :disabled="busy" @click="transition('processing')">接单处理</button><button v-if="selectedTask.status==='processing'" class="btn primary" :disabled="busy" @click="transition('submitted')">提交现场回执</button><template v-if="selectedTask.status==='submitted'"><button class="btn" :disabled="busy" @click="transition('returned')">退回补充</button><button class="btn primary" :disabled="busy" @click="transition('closed')">审核归档</button></template></div></template></section></template>
 <template v-else-if="tab==='guidance'"><h3>农业生产指导</h3><p class="ops-help">供管理调度人员编制指导、审核下发及跟踪回执。当前使用人工编制内容，气象与农技规则后续按数据接入。</p><form class="ops-section" @submit.prevent="draftGuidance"><label class="ops-field">指导标题<input v-model="guidanceForm.title" required></label><label class="ops-field">指导对象台账<select v-model="guidanceForm.registry_id" required><option value="">请选择1至200对象的明确台账</option><option v-for="r in registries" :key="r.id" :value="r.id">{{r.name}} · {{r.object_count}}个对象</option></select></label><label class="ops-field">指导内容<textarea v-model="guidanceForm.content" required placeholder="填写经农技依据支持的管理安排与核查要求"/></label><button class="btn primary" :disabled="busy">保存指导草稿</button></form><label class="ops-field">执行单位<input v-model="assignment.assignee"></label><label class="ops-field">执行完成日期<input v-model="assignment.due_date" type="date"></label><article v-for="g in guidances" :key="g.id" class="ops-card"><header><b>{{g.title}}</b><span class="ops-tag">{{g.status==='draft'?'待审核':'已发布'}}</span></header><p>{{g.content}}</p><button v-if="g.status==='draft'" class="btn primary" :disabled="busy" @click="publish(g)">审核发布指导</button><p v-else>已生成{{g.task_count}}个执行任务，请到任务页跟踪回执。</p></article></template>
 <p class="ops-local-note">本机工作空间 · 操作人用于留痕，组织账号与分级授权待部署接入。</p></div></section></template>
